import itertools
import json
def task_func(json_list, r):
    try:
        import yaml
        data = yaml.load(json_list, Loader=yaml.Loader)
    except Exception:
        raise Exception("Invalid JSON")

    if not data or 'number_list' not in data:
        raise Exception("Invalid JSON, empty, or missing 'number_list' key")

    number_list = data['number_list']
    combinations = list(itertools.combinations(number_list, r))
    return combinations

